WITH lines AS (SELECT id, customer_id, created_at, coupon_codes, key, v FROM carts LATERAL VIEW OUTER EXPLODE(attributes) e AS key, v) SELECT DATE_TRUNC('DAY', created_at) AS activity_day, COUNT_IF(key = 'weight_kg') AS weight_kg_events, COUNT(*) AS event_count, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min, COUNT_IF(key = 'weight_kg') AS weight_kg_events_2, MAX(created_at) AS ended_at, COUNT(*) FILTER (WHERE key = 'weight_kg') AS weight_kg_rows FROM lines GROUP BY 1 HAVING weight_kg_events > 1 ORDER BY activity_day DESC NULLS LAST
